/**
 * Every outcome is distinguishable. "Not enough turns to judge" and "healthy"
 * are different answers, and a check that could not run is neither — collapsing
 * them is how a monitor reports all-clear through an outage.
 */
export type ChatHealthAlertOutcome = {
    status: "healthy";
    turns: number;
    badRate: number;
} | {
    status: "insufficient-data";
    turns: number;
} | {
    status: "cooldown";
    retryAfterMs: number;
} | {
    status: "alerted";
    turns: number;
    badRate: number;
    recipients: number;
} | {
    status: "delivery-failed";
    reason: string;
} | {
    status: "persistence-failed";
    reason: string;
} | {
    status: "check-failed";
    reason: string;
};
export declare function checkChatHealthAndAlert(now?: number): Promise<ChatHealthAlertOutcome>;
